import { createPagesFunctionHandler } from "@react-router/cloudflare";
import { RouterContextProvider, type ServerBuild } from "react-router";

// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore - the server build file is generated by `react-router build`
// eslint-disable-next-line import/no-unresolved
import * as build from "../build/server";

const remixHandler = createPagesFunctionHandler({
  // Resource routes (api.*) have no default export, which ServerBuild's route
  // module type requires, so the generated build does not type-check as one
  // whenever build/ exists. It is a valid server build at runtime.
  build: build as unknown as ServerBuild,
  getLoadContext: () => new RouterContextProvider(),
});

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "*",
  "Access-Control-Allow-Methods": "GET, OPTIONS",
  "Access-Control-Max-Age": "86400",
};

export const onRequest = async (context: EventContext<unknown, string, unknown>) => {
  const { request } = context;

  if (request.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  const response = await remixHandler(context);
  for (const [key, value] of Object.entries(corsHeaders)) {
    response.headers.set(key, value);
  }

  return response;
};
